using System.Data;using System.Text;using Dapper;using Microsoft.Data.SqlClient;using Microsoft.Extensions.Configuration;using GraphApi.Models.VTS.LogUsoVisitas;namespace GraphApi.Services.VTS.LogUsoVisitas{    public class LogUsoVisitasService : ILogUsoVisitasService    {        private readonly IDbConnection   _objDbDefault;        private readonly IConfiguration  _objConfig;        public LogUsoVisitasService(IDbConnection objDbDefault, IConfiguration objConfig)        {            _objDbDefault = objDbDefault;            _objConfig    = objConfig;        }        public async Task<IEnumerable<clReadLogUsoVisitas>> GetLogUsoVisitas(            int userId,            string windowName)        {            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT  *                 FROM vts.LogUsoVisitas (NOLOCK)            ");            var vParameters = new DynamicParameters();            var vList = await _objDbDefault.QueryAsync<clReadLogUsoVisitas>(vSql.ToString(), vParameters);            return vList;        }        public async Task<IEnumerable<dynamic>> GetLogUsoVisitasDynamic(            int? logUsoVisitaID,            int? visitaGeneradaID,            DateTime? fechaAcceso,            string? iPOrigen,            string? userAgent,            bool? exitoso,            bool? bEliminado,            string? columnNames,            int userId,            string windowName)        {            string sColumnNames = string.IsNullOrWhiteSpace(columnNames) ? "LogUsoVisitaID, VisitaGeneradaID, FechaAcceso, IPOrigen, UserAgent, Exitoso, bEliminado" : columnNames;            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT {sColumnNames}                FROM vts.LogUsoVisitas (NOLOCK)                WHERE 1=1            ");            var vParameters = new DynamicParameters();            if (logUsoVisitaID.HasValue)            {                vSql.Append(" AND LogUsoVisitaID = @LogUsoVisitaID");                vParameters.Add("LogUsoVisitaID",logUsoVisitaID);            }            if (!string.IsNullOrWhiteSpace(iPOrigen))            {                vSql.Append(" AND IPOrigen LIKE @IPOrigen");                vParameters.Add("IPOrigen",$"%{iPOrigen}%");            }            if (!string.IsNullOrWhiteSpace(userAgent))            {                vSql.Append(" AND UserAgent LIKE @UserAgent");                vParameters.Add("UserAgent",$"%{userAgent}%");            }            if (exitoso.HasValue)            {                vSql.Append(" AND Exitoso = @Exitoso");                vParameters.Add("Exitoso", exitoso.Value);            }            if (bEliminado.HasValue)            {                vSql.Append(" AND bEliminado = @bEliminado");                vParameters.Add("bEliminado", bEliminado.Value);            }            var vList = await _objDbDefault.QueryAsync<dynamic>(vSql.ToString(), vParameters);            return vList;        }        public async Task<clReadLogUsoVisitas> CreateLogUsoVisitas(clCreateLogUsoVisitas objInput, int userId, string windowName)        {            string sInsertSql = $@"                --WindowName:{windowName},UserID:{userId}                INSERT INTO vts.LogUsoVisitas                (VisitaGeneradaID, FechaAcceso, IPOrigen, UserAgent, Exitoso, bEliminado, Creado, UsuarioCreacionID, FechaCreacion)                VALUES (@VisitaGeneradaID, @FechaAcceso, @IPOrigen, @UserAgent, @Exitoso, @bEliminado, @Creado, @UsuarioCreacionID, GETDATE());                SELECT CAST(SCOPE_IDENTITY() AS INT);            ";            var vInsertParams = new            {                objInput.VisitaGeneradaID,                objInput.FechaAcceso,                objInput.IPOrigen,                objInput.UserAgent,                objInput.Exitoso,                objInput.bEliminado,                Creado     = windowName,                UsuarioCreacionID = userId            };            var vNewId = await _objDbDefault.ExecuteScalarAsync<int>(sInsertSql, vInsertParams);            string sSelectSql = @"                SELECT LogUsoVisitaID, VisitaGeneradaID, FechaAcceso, IPOrigen, UserAgent, Exitoso, bEliminado                FROM vts.LogUsoVisitas (NOLOCK)                WHERE LogUsoVisitaID = @LogUsoVisitaID;";            var vReadParams = new { LogUsoVisitaID = vNewId };            var vCreated = await _objDbDefault.QuerySingleOrDefaultAsync<clReadLogUsoVisitas>(sSelectSql, vReadParams);            if (vCreated is null) throw new InvalidOperationException($"No se pudo recuperar el LogUsoVisita con ID {vNewId}.");            return vCreated;        }        public async Task<clReadLogUsoVisitas?> UpdateLogUsoVisitas(clUpdateLogUsoVisitas objInput, int userId, string windowName)        {            var vSets = new List<string>();            var vParameters = new DynamicParameters();            vParameters.Add("LogUsoVisitaID", objInput.LogUsoVisitaID);            if (objInput.VisitaGeneradaID != null)            {                vSets.Add("VisitaGeneradaID = @VisitaGeneradaID");                vParameters.Add("VisitaGeneradaID", objInput.VisitaGeneradaID);            }            if (objInput.FechaAcceso != null)            {                vSets.Add("FechaAcceso = @FechaAcceso");                vParameters.Add("FechaAcceso", objInput.FechaAcceso);            }            if (objInput.IPOrigen is not null)            {                vSets.Add("IPOrigen = @IPOrigen");                vParameters.Add("IPOrigen", objInput.IPOrigen);            }            if (objInput.UserAgent is not null)            {                vSets.Add("UserAgent = @UserAgent");                vParameters.Add("UserAgent", objInput.UserAgent);            }            if (objInput.Exitoso != null)            {                vSets.Add("Exitoso = @Exitoso");                vParameters.Add("Exitoso", objInput.Exitoso);            }            if (objInput.bEliminado != null)            {                vSets.Add("bEliminado = @bEliminado");                vParameters.Add("bEliminado", objInput.bEliminado);            }            vSets.Add($"Modificado = '{windowName}'");            vSets.Add($"UsuarioModificacionID = {userId}");            vSets.Add("FechaModificacion = GETDATE()");            var vSetClause = string.Join(", ", vSets);            var sSql = $@"                --WindowName:{windowName},UserID:{userId}                UPDATE vts.LogUsoVisitas                SET {vSetClause}                WHERE LogUsoVisitaID = @LogUsoVisitaID;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, vParameters);            if (vAffected == 0) return null;            const string sSelect = @"                SELECT LogUsoVisitaID, VisitaGeneradaID, FechaAcceso, IPOrigen, UserAgent, Exitoso, bEliminado                FROM vts.LogUsoVisitas (NOLOCK)                WHERE LogUsoVisitaID = @LogUsoVisitaID;";            return await _objDbDefault.QueryFirstOrDefaultAsync<clReadLogUsoVisitas>(sSelect, new {  objInput.LogUsoVisitaID });        }        public async Task<bool> DeleteLogUsoVisitas(int nLogUsoVisitasID)        {            const string sSql = @"                DELETE FROM vts.LogUsoVisitas                WHERE LogUsoVisitaID = @Id;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, new { Id = nLogUsoVisitasID });            return vAffected > 0;        }    }}